<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted } from 'vue';
import { usePortfolioStore } from '../stores/portfolio';
import { companies } from '../data/companies';

const store = usePortfolioStore();
const company = computed(() => companies[store.companyIndex]);
const isAr = computed(() => store.language === 'ar');
let observer: MutationObserver | undefined;
onMounted(() => { const sync = () => store.setLanguage(document.documentElement.lang === 'en' ? 'en' : 'ar'); sync(); observer = new MutationObserver(sync); observer.observe(document.documentElement, { attributes: true, attributeFilter: ['lang', 'dir'] }); });
onBeforeUnmount(() => observer?.disconnect());
function contactHref(c: any) { const subject = isAr.value ? `مناقشة منتجات — ${c.nameAr}` : `Products discussion — ${c.nameEn}`; return `mailto:partners@targetft.com?subject=${encodeURIComponent(subject)}`; }
</script>

<template>
  <section class="portfolio-app" :dir="isAr ? 'rtl' : 'ltr'">
    <div class="portfolio-company-grid" role="tablist" :aria-label="isAr ? 'الشركات والمنتجات محل الاهتمام' : 'Companies and products in focus'">
      <button v-for="(c, ci) in companies" :key="c.id" type="button" class="company-tile" :class="{ active: store.companyIndex === ci }" role="tab" :aria-selected="store.companyIndex === ci" @click="store.selectCompany(ci)">
        <span class="company-tile-top"><span class="company-tile-mark">{{ String(ci + 1).padStart(2, '0') }}</span><span class="company-tile-state">{{ isAr ? 'استعرض السجل' : 'View record' }}</span></span><span class="company-tile-content"><span class="company-kicker">{{ isAr ? 'ضمن نطاق الاهتمام' : 'Within current focus' }}</span><strong>{{ isAr ? c.nameAr : c.nameEn }}</strong><small>{{ isAr ? c.categoryAr : c.categoryEn }}</small><span class="company-count">{{ c.products.length }} {{ isAr ? 'أصناف مدرجة' : 'listed items' }}</span></span>
      </button>
    </div>
    <article class="portfolio-detail" role="tabpanel">
      <header class="company-summary"><span class="portfolio-label">{{ isAr ? 'شركات ومنتجات محل اهتمامنا' : 'Companies & Products in Focus' }}</span><h3>{{ isAr ? company.nameAr : company.nameEn }}</h3><p class="company-category">{{ isAr ? company.categoryAr : company.categoryEn }}</p><p class="company-description">{{ isAr ? company.descriptionAr : company.descriptionEn }}</p><p v-if="'noteAr' in company" class="company-note">{{ isAr ? company.noteAr : company.noteEn }}</p><div class="claim-note"><i class="bi bi-shield-check"></i><span>{{ isAr ? 'عرض تعريفي فقط؛ ولا يعني وكالة أو تمثيلًا أو حصرية.' : 'For information only; no agency, representation or exclusivity is implied.' }}</span></div></header>
      <section class="company-products" :aria-label="isAr ? 'الأصناف المسجلة' : 'Listed products'"><div class="company-products-head"><div><span class="portfolio-label">{{ isAr ? 'الأصناف المسجلة' : 'Listed products' }}</span><h3>{{ isAr ? `منتجات ${company.nameAr}` : `${company.nameEn} products` }}</h3></div><span class="product-count">{{ company.products.length }} {{ isAr ? 'صنفًا' : 'items' }}</span></div><p class="products-intro">{{ isAr ? 'الأسماء التالية مستندة إلى مصدر المحتوى المعتمد. تُضاف صور العبوات أو ملفات المنتجات بعد اعتمادها.' : 'The names below follow the approved content source. Product images or files are added after approval.' }}</p><ul class="company-product-list"><li v-for="(p, pi) in company.products" :key="p.slug"><span>{{ String(pi + 1).padStart(2, '0') }}</span>{{ isAr ? p.nameAr : p.nameEn }}</li></ul><a class="portfolio-contact" :href="contactHref(company)"><i class="bi bi-envelope"></i>{{ isAr ? 'ناقش المنتجات' : 'Discuss products' }}</a></section>
    </article>
  </section>
</template>

