.portfolio-detail{padding:8px;border:1px solid rgba(12,73,49,.08);border-radius:24px;background:linear-gradient(145deg,#edf4ef,#fbf8f2)}.company-summary{position:relative;overflow:hidden;border:0;background:linear-gradient(155deg,#0c5138,#073b29);color:#fff;box-shadow:0 18px 36px rgba(7,59,41,.15)}.company-summary::after{content:'';position:absolute;inset-inline-end:-80px;inset-block-start:-70px;width:230px;height:230px;border-radius:50%;background:radial-gradient(circle,rgba(216,184,121,.28),transparent 67%)}.company-summary>*{position:relative;z-index:1}.company-summary .portfolio-label{color:#e3c38d}.company-summary h3{color:#fff}.company-summary .company-category{color:#e6c993}.company-summary .company-description{color:rgba(255,255,255,.78)}.company-summary .company-note{background:rgba(255,255,255,.10);color:rgba(255,255,255,.84)}.company-summary .claim-note{background:rgba(255,255,255,.11);color:#fff}.company-products{border:0;box-shadow:none}.company-product-list li{transition:border-color .18s ease,transform .18s ease;background:#fff}.company-product-list li:hover{border-color:#cfa66b;transform:translateY(-1px)}.portfolio-contact{min-height:50px;border-radius:13px;box-shadow:0 10px 20px rgba(12,73,49,.16)}
